    vecISToVCMatrix[0] = sizeVC[0];
    vecISToVCMatrix[4] = sizeVC[1];
    vecISToVCMatrix[8] = sizeVC[2];
    // Then apply the image direction matrix
    esm/* mat3.multiply */.w0.multiply(vecISToVCMatrix, imageDirection, vecISToVCMatrix);
    // Then apply the actor matrix
    esm/* mat3.multiply */.w0.multiply(vecISToVCMatrix, actMats.normalMatrix, vecISToVCMatrix);
    // Then apply the camera matrix
    esm/* mat3.multiply */.w0.multiply(vecISToVCMatrix, keyMats.normalMatrix, vecISToVCMatrix);
    program.setUniformMatrix3x3(`${uniformPrefix}.vecISToVCMatrix`, vecISToVCMatrix);
    program.setUniformMatrix3x3(`${uniformPrefix}.vecVCToISMatrix`, esm/* mat3.invert */.w0.invert(new Float32Array(9), vecISToVCMatrix));

    // Set originVC uniform that will be used to convert points from IS to VC
