      program.setUniformi(`${uniformPrefix}.kernelSize`, kernelSize);
      const kernelRadius = firstVolumeProperty.getLAOKernelRadius();
      program.setUniformi(`${uniformPrefix}.kernelRadius`, kernelRadius);
